'use strict';
const V265={
 progress(p){if(!p)return '';const rows=[['计划净重',p.planned_net_weight],['溢短装（%）',p.quantity_tolerance],['允许最大净重',p.maximum_weight],['最低允许净重',p.minimum_weight],['当前累计有效净重',p.effective_net_weight],['尚未出库的有效分配净重',p.assigned_net_weight],['已正式出库净重',p.outbound_net_weight],['已释放净重',p.released_net_weight],['剩余可用净重额度',p.remaining_weight],['计划备货批次数量',p.planned_lot_count],['已使用Lot数量',p.used_lot_count],['剩余可创建Lot数量',p.remaining_lot_count],['发运月份',p.preparation_month]];return `<div class="overview-ledger">${rows.map(([k,v])=>`<p><span>${k}</span><br><strong data-no-i18n>${v==null?'—':esc(k.includes('净重')?Tonnes.format(v):v)}</strong>${k.includes('净重')?' <span>吨</span>':''}</p>`).join('')}</div>${!p.fields_complete?'<p class="dialog-notice">请补齐计划控制字段</p>':''}${p.unknown_bundles?'<p class="dialog-notice">重量尚未完全确定</p>':''}${p.over_limit?'<p class="error">销售计划数量超限，已保留真实检斤数据</p>':''}`;},
 cards(data,type){const pairs=type==='preparation'?[['WORKING','备货作业中',data.preparation?.WORKING],['PENDING','待主管审核',data.preparation?.PENDING],['PREPARED','已备货',data.preparation?.PREPARED],['RECTIFY','已驳回/待整改',data.preparation?.RECTIFY]]:[['PENDING','装车待审核',data.loading],['DEPARTED_PENDING','正式出库待审批',data.final_outbound]];return `<div class="approval-cards">${pairs.map(([state,label,n])=>`<a class="approval-card" href="/${type==='preparation'?'preparation':'outbounds'}?status=${state}"><span>${label}</span>${UI.number(n??0)}<small>${type==='preparation'?'批':'单'}</small></a>`).join('')}</div>`;},
 async refresh(){if(!window.AppSignedIn)return;try{const d=await API.request('/workflow/approvals');for(const [route,keys] of [['preparation',['preparation']],['outbounds',['loading','final_outbound']]])for(const a of document.querySelectorAll(`[data-primary-route="${route}"]`)){a.querySelectorAll('.v265-badge').forEach(x=>x.remove());for(const key of keys)if(d.pending[key]>0){const badge=document.createElement('span');badge.className='approval-badge v265-badge';badge.textContent=(key==='loading'?'装车':key==='final_outbound'?'出库':'')+' '+d.pending[key];badge.title=key==='final_outbound'?'正式出库待审批':key==='loading'?'装车待审核':'待主管审核';badge.onclick=e=>{e.preventDefault();e.stopPropagation();Router.go('/'+route+'?status='+(key==='final_outbound'?'DEPARTED_PENDING':'PENDING'));};a.append(badge);}}if($('v265-approval-cards'))$('v265-approval-cards').innerHTML=this.cards(d,location.pathname.startsWith('/preparation')?'preparation':'outbounds');}catch(e){document.querySelectorAll('.v265-badge').forEach(b=>{b.textContent='!';b.title=e.message;});}},
 async checkInputs(kind){const inputs=[...document.querySelectorAll(kind==='bundle'?'#v26-receipt-lines [data-field="bundle_no"]':'[data-v262-seal]')].filter(i=>i.value.trim());if(!inputs.length)return;const stamp=inputs.map(i=>i.value).join('\0');try{const result=await API.request('/identity/check',{method:'POST',body:{kind,receipt_id:kind==='bundle'?$('v26-receipt')?.dataset.receiptId||undefined:undefined,items:inputs.map(i=>({value:i.value,bundle_id:i.dataset.v262Seal}))}});if(inputs.map(i=>i.value).join('\0')!==stamp)return;for(const i of inputs){i.removeAttribute('aria-invalid');i.nextElementSibling?.classList.contains('v265-conflict')&&i.nextElementSibling.remove();}for(const c of result.conflicts){const input=inputs[c.row];input.setAttribute('aria-invalid','true');const note=document.createElement('small');note.className='error v265-conflict';const other=[...new Set((c.sources||[]).map(s=>s.bundle_no).filter(Boolean))].join('、')||c.value;note.innerHTML='<span data-i18n-key="conflict.prefix">与</span><span data-no-i18n>'+esc(other)+'</span><span data-i18n-key="conflict.'+(kind==='bundle'?'bundle':'seal')+'.suffix">'+(kind==='bundle'?'捆包编号冲突，请核对':'捆包铅封号冲突，请核对')+'</span>';input.after(note);}}catch(e){notify(I18n.translate('编号验证暂不可用，请重新检查')+' '+e.message);}},
 async start(){await this.refresh();window.addEventListener('inventory-changed',()=>{clearTimeout(this.timer);this.timer=setTimeout(()=>this.refresh(),150);});window.addEventListener('focus',()=>this.refresh());setInterval(()=>{if(!document.hidden)this.refresh();},60000);document.addEventListener('input',e=>{let kind=e.target.matches('[data-v262-seal]')?'seal':e.target.matches('#v26-receipt-lines [data-field="bundle_no"]')?'bundle':null;if(kind){clearTimeout(this.identityTimer);this.identityTimer=setTimeout(()=>this.checkInputs(kind),450);}});}
};
const v265PlanForm=Business.planForm.bind(Business);
Business.planForm=async function(p={}){await v265PlanForm(p);const form=$('plan-form');const controls=document.createElement('div');controls.className='form-grid';controls.innerHTML=`<label>溢短装（%）<input name="quantity_tolerance" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" value="${esc(p.quantity_tolerance??'')}" required></label><label>发运月份<input name="preparation_month" type="month" value="${esc(p.preparation_month??'')}" required></label><label>计划备货批次数量<input name="planned_lot_count" type="number" min="1" max="2147483647" step="1" value="${esc(p.planned_lot_count??'')}" required></label>`;$('plan-error').before(controls);if(p.id){const detail=document.createElement('section');detail.className='panel';detail.innerHTML=V265.progress(await API.request('/plans/'+p.id+'/progress'));form.after(detail);}};
const v265Create=V261.create.bind(V261);
V261.create=async function(){await v265Create();const selector=$('v261-plan'),info=document.createElement('section');info.id='v265-plan-progress';info.className='panel';$('v261-plan-info').after(info);let seq=0;const update=async()=>{const n=++seq;try{const p=selector.value?await API.request('/plans/'+selector.value+'/progress'):null;if(n===seq)info.innerHTML=V265.progress(p);}catch(e){info.textContent=e.message;}};selector.addEventListener('change',update);await update();};
const v265Receipt=Business.receiptEditor.bind(Business);
Business.receiptEditor=async function(r={}){await v265Receipt(r);if($('v26-receipt'))$('v26-receipt').dataset.receiptId=r.id||'';};
for(const [object,name,type] of [[V261,'allocations','preparation'],[V26,'loads','outbounds']]){const prior=object[name].bind(object);object[name]=async function(){await prior();const panel=document.createElement('section');panel.id='v265-approval-cards';$('page-content').prepend(panel);await V265.refresh();};}
Business.allocations=V261.allocations.bind(V261);
Business.allocationEditor=V261.create.bind(V261);
Flow.loads=V26.loads.bind(V26);
Flow.outbounds=V26.loads.bind(V26);
